import reflex as rx
import hashlib
import secrets

# Seeded users credentials hashed at startup
def hash_password(password: str, salt: bytes = None) -> tuple[str, bytes]:
    """Hash a password with a salt using PBKDF2 HMAC SHA-256."""
    if salt is None:
        salt = secrets.token_bytes(16)
    key = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return key.hex(), salt

def verify_password(password: str, hashed_hex: str, salt: bytes) -> bool:
    """Verify a password against a hash and salt."""
    key = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return key.hex() == hashed_hex

# Precompute hashes for seeded users
admin_hash, admin_salt = hash_password("s3cure-admin-pw")
alice_hash, alice_salt = hash_password("s3cure-user-pw")

class State(rx.State):
    # Backend-only state variables (prefixed with _)
    _users: dict[str, dict] = {
        "admin": {
            "hash": admin_hash,
            "salt": admin_salt,
            "role": "admin"
        },
        "alice": {
            "hash": alice_hash,
            "salt": alice_salt,
            "role": "user"
        }
    }
    _session_username: str = ""
    _session_role: str = ""

    # Public state variables
    error_message: str = ""

    @rx.var
    def is_authenticated(self) -> bool:
        return self._session_username != ""

    @rx.var
    def is_admin(self) -> bool:
        return self._session_role == "admin"

    @rx.var
    def logged_in_username(self) -> str:
        return self._session_username

    @rx.var
    def logged_in_role(self) -> str:
        return self._session_role

    def login(self, form_data: dict[str, str]):
        username = form_data.get("username", "").strip()
        password = form_data.get("password", "")

        if username in self._users:
            user_data = self._users[username]
            if verify_password(password, user_data["hash"], user_data["salt"]):
                self._session_username = username
                self._session_role = user_data["role"]
                self.error_message = ""
                return rx.redirect("/dashboard")

        self.error_message = "Invalid credentials"

    def logout(self):
        self._session_username = ""
        self._session_role = ""
        self.error_message = ""
        return rx.redirect("/login")

    def check_root_access(self):
        if self.is_authenticated:
            return rx.redirect("/dashboard")
        else:
            return rx.redirect("/login")

    def check_dashboard_access(self):
        if not self.is_authenticated:
            return rx.redirect("/login")

    def check_admin_access(self):
        if not self.is_authenticated:
            return rx.redirect("/login")
        if not self.is_admin:
            return rx.redirect("/forbidden")


@rx.page(route="/", on_load=State.check_root_access)
def index() -> rx.Component:
    return rx.fragment()


@rx.page(route="/login")
def login_page() -> rx.Component:
    return rx.center(
        rx.vstack(
            rx.heading("Login", size="8", margin_bottom="4"),
            rx.form(
                rx.vstack(
                    rx.input(
                        name="username",
                        placeholder="Username",
                        width="100%",
                        required=True,
                    ),
                    rx.input(
                        name="password",
                        placeholder="Password",
                        type="password",
                        width="100%",
                        required=True,
                    ),
                    rx.button("Login", type="submit", width="100%"),
                    spacing="3",
                    width="100%",
                ),
                on_submit=State.login,
                width="100%",
            ),
            rx.cond(
                State.error_message,
                rx.text(State.error_message, color="red", font_size="14px", margin_top="2"),
            ),
            spacing="4",
            padding="6",
            border_radius="lg",
            border="1px solid #eaeaea",
            box_shadow="md",
            bg="white",
            width="350px",
        ),
        min_height="100vh",
        bg="#f9f9f9",
